/* Explicit-call backend for a SEPARATE worker process, never camera-service.
 * No constructors, patches, USB, filesystem writes, or lens commands.
 * ABI anchors are generated by build_pdaf425.py from the audited stock ELF.
 */
#include "pdaf425_core.h"
#include "pdaf425_guards.h"
extern void *dlopen(const char *, int);
extern void *dlsym(void *, const char *);
extern int clock_gettime(int, void *);
struct p425_timespec { long sec, nsec; };
struct native_worker {
    void *library;
    p425_u64 base;
    int (*create)(int, const void *);
    int (*calc)(int, const void *, const void *);
    void (*results)(int, void *);
    const struct p425_frame *pinned;
};
static p425_u64 clock_us(void *unused) {
    (void)unused;
    struct p425_timespec ts;
    if (clock_gettime(1,&ts)!=0 || ts.sec<0 || ts.nsec<0) return 0;
    return (p425_u64)ts.sec*1000000u+(p425_u64)ts.nsec/1000u;
}
static int same_frame(void *v, const struct p425_frame *f) {
    return ((struct native_worker *)v)->pinned==f;
}
static int calculate(void *v, const struct p425_frame *f,
                     const p425_u8 *cfg, p425_u8 *out) {
    struct native_worker *w=v;
    /* extract_pdaf_pixels reads the raw-plane pointer at input offset zero. */
    const void *raw_descriptor[1]={f->raw};
    p425_u8 *ctx=*(p425_u8 **)(unsigned long)(w->base+P425_CONTEXT_SLOT);
    if (!ctx) return -1;
    /* Clear only this worker's result record: a failed calculation must not
     * expose the previous ROI's result as a new measurement. */
    for (unsigned int j=0;j<0x58;++j) ctx[0x34c+j]=0;
    ctx[0x7d8]=0;
    if (w->calc(0,cfg,raw_descriptor)!=0) return -1;
    p425_u32 local=(p425_u32)ctx[0xa8]|((p425_u32)ctx[0xa9]<<8)|
                      ((p425_u32)ctx[0xaa]<<16)|((p425_u32)ctx[0xab]<<24);
    p425_u32 nx=ctx[0xcc22]|((p425_u32)ctx[0xcc23]<<8);
    p425_u32 ny=ctx[0xcc24]|((p425_u32)ctx[0xcc25]<<8);
    if (local!=1 || nx>126 || ny>126 || nx*ny>126) return -1;
    w->results(0,out);
    return 0;
}
/* Caller must own a coherent copied raw frame/config and use an isolated
 * process. This entry does not acquire or verify producer-frame coherence.
 * No active AF consumer is connected to its returned measurement records.
 */
int p425_native_measure(const struct p425_frame *f, p425_u64 budget,
                         struct p425_result *out) {
    struct p425_roi plan[P425_COUNT];
    if (!out) return P425_INPUT;
    p425_u8 *result_bytes=(p425_u8 *)out;
    for (unsigned long i=0;i<sizeof(*out);++i) result_bytes[i]=0;
    if (p425_plan(f,plan)!=0) return P425_INPUT;
    struct native_worker w={0};
    w.library=dlopen("/system/lib64/libaaa.so",2);
    if (!w.library) return P425_BACKEND;
    w.create=(int (*)(int,const void *))dlsym(w.library,"pdaf_type3_stats_lib_create");
    w.calc=(int (*)(int,const void *,const void *))dlsym(w.library,"pdaf_type3_stats_lib_calc");
    w.results=(void (*)(int,void *))dlsym(w.library,"pdaf_type3_stats_lib_get_results");
    if (!w.create || !w.calc || !w.results) return P425_BACKEND;
    w.base=(p425_u64)(unsigned long)w.calc-P425_CALC_VA;
    /* Reject a reused live context rather than resetting its state. */
    for (unsigned int i=0;i<32;++i)
        if (*(void **)(unsigned long)(w.base+P425_CONTEXT_SLOT+8u*i)) return P425_BACKEND;
    void *functions[3]={(void *)w.create,(void *)w.calc,(void *)w.results};
    for (unsigned int i=0;i<3;++i) {
        if ((p425_u64)(unsigned long)functions[i]!=w.base+p425_guards[i].va)
            return P425_BACKEND;
    }
    for (unsigned int i=0;i<P425_GUARD_COUNT;++i) {
        const p425_u8 *bytes=(const p425_u8 *)(unsigned long)(w.base+p425_guards[i].va);
        for (unsigned int j=0;j<p425_guards[i].size;++j)
            if (bytes[j]!=p425_guards[i].bytes[j]) return P425_BACKEND;
    }
    if (w.create(0,f->config)!=0) return P425_BACKEND;
    w.pinned=f;
    struct p425_backend b={&w,calculate,clock_us,same_frame};
    return p425_process(f,&b,budget,out);
    /* One measurement session per worker; worker exit releases native state. */
}
